            lock (_lock)
            {
                if (!_registries.TryGetValue(module, out registry!)) _registries[module] = registry = new Dictionary<object, long>(PyKeyComparer.Instance!);
            }
            WarnExplicit(message, category, filename, lineno, module, registry, source);
