            return new PyClosure("deprecated", (a, kw) =>
            {
                if (a.Length != 1) throw new InvalidCastException("deprecated() takes exactly one argument (the function or class)");
                object? arg = a[0];
                if (cat == null || arg is Type) return arg;
                if (arg is not PyFunction && arg is not Delegate && arg is not PyBoundMethod)
                    throw new InvalidCastException($"@deprecated decorator with non-None category must be applied to a class or callable, not {Builtins.repr(arg)}");
