        /// <summary>The Python version _deprecated compares remove= with (Typhon follows CPython 3.15).</summary>
        static readonly (long, long, long, string, long) Version = (3, 15, 0, "final", 0);

        /// <summary>
        /// _deprecated(name, message=_DEPRECATED_MSG, *, remove): the stdlib's helper. A DeprecationWarning at the caller of
        /// the deprecated module's code, or RuntimeError when Python version remove=(major, minor) is already here.
        /// </summary>
